import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"効果音と読み上げを設定する","description":"","frontmatter":{"title":"効果音と読み上げを設定する","docId":"user.plugins.audio","translationKey":"user.plugins.audio","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e0e5014682213e36dda2e4c02293b8f960f3c107bdb1679327fb00b92e02604b","translationRevision":"6e4d0299813535c37c19bdd42b223f965e91ebdc7a203cb5fd5091642468400c","order":20},"headers":[],"relativePath":"ja/user/plugins/audio.md","filePath":"ja/user/plugins/audio.md","lastUpdated":1795727787000}`),a={name:`ja/user/plugins/audio.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="set-up-sounds-and-speech" tabindex="-1">効果音と読み上げを設定する <a class="header-anchor" href="#set-up-sounds-and-speech" aria-label="Permalink to “効果音と読み上げを設定する”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目的と前提条件”">​</a></h2><p>混雑した LIVE に音声を連動させる前に、予測できる音を再生します。正常な出力機器と対応する既存音声ファイルが必要です。ローカルの <strong>サウンドを再生</strong> (<code>audio.play</code>) は組み込みアクションです。SonicBoom などの読み上げ連携には専用プラグイン・サービスの設定が必要です。</p><h2 id="test-a-local-sound" tabindex="-1">ローカル音声を試す <a class="header-anchor" href="#test-a-local-sound" aria-label="Permalink to “ローカル音声を試す”">​</a></h2><ol><li><strong>自動化 → アクション</strong> で <strong>サウンドを再生</strong> (<code>audio.play</code>) を作り、メディア選択で既存ファイルを指定します。</li><li>最初は音量 <code>0.2</code> にします。範囲は <code>0</code>～<code>1</code> で、ゼロは無音です。</li><li>重複時の方針を選びます。<code>allow</code> は同時再生、<code>restart</code> は最初から再生、<code>drop</code> は再生中の新しい要求を無視します。</li><li>保存して設定を読み、<strong>テストを実行</strong> を選びます。このテストでは実際に音が鳴ることがあります。</li><li>目的の機器で聞きます。ローカル再生が成功してから、控えめな<a href="./../automations/recipes.html">フィルターとクールダウン</a> を持つイベントに関連付けます。</li></ol><p>アクションはパスに基づくメディア参照を保持し、音声ファイルを DB にコピーしません。ファイルをそのパスに保ち、移行やバックアップでは別途含めてください。</p><h2 id="configure-optional-speech" tabindex="-1">任意の読み上げ機能を設定する <a class="header-anchor" href="#configure-optional-speech" aria-label="Permalink to “任意の読み上げ機能を設定する”">​</a></h2><p>信頼できる読み上げプラグインを <a href="./">プラグイン</a> からインストールします。接続・設定でサービスアドレス、認証、プロバイダー、言語、音声・プロファイルを確認します。音声カタログを読み込んでから、機密性のない短文をテストします。音声がない場合は架空の ID で代用せず、カタログ、所有権、プロバイダーの不一致を調べます。</p><p>SonicBoom では合成、再生受付、聞こえるまでの完了は別の結果です。待機列への追加や開始応答だけでは、人が聞けたことは確認できません。クローン音声はチャットの到着より遅い場合があるため、待機列・飽和の診断を確認し、イベント受付数を制限します。</p><h2 id="expected-result-status-and-recovery" tabindex="-1">期待される結果・提供状況と対処 <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to “期待される結果・提供状況と対処”">​</a></h2><p>ホストが音声対応を通知していればローカル再生を利用できます。読み上げはインストール済みプラグインと接続可能なサービスに依存し、各プロバイダー・機器・プラットフォームでの動作は保証されません。無音ならファイル、音量、出力機器、一時停止、実行エラーを確認します。読み上げ失敗ではサービスと音声カタログを調べてから再試行します。配信中の繰り返しテストを避け、<a href="./../preferences/troubleshooting.html">診断</a> ではトークンや読み上げた非公開文を共有しないでください。</p><h2 id="command-line-operations" tabindex="-1">コマンドライン操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “コマンドライン操作”">​</a></h2><p>このガイドのすべての操作はCLIからも利用できます——オフライン、スクリプト可能、エージェント対応。使用法の行はパーサー構文であり、すべての言語で英語のままです。</p><table tabindex="0"><thead><tr><th>コマンド</th><th>概要</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>アクションで使用する前にメディアファイルを検証</td></tr></tbody></table><p>規約、JSON出力、破壊的操作のマーカーについては<a href="./../../developer/cli.html">完全なコマンドリファレンス</a>を参照してください。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};